from collections import Counter

def analyze_pattern_v4(input_grid):
    h, w = len(input_grid), len(input_grid[0])
    bg = Counter(x for row in input_grid for x in row).most_common(1)[0][0]
    corner_pos = [(r, c) for r in range(h) for c in range(w) if input_grid[r][c] == 0]
    seed_pos = [(r, c) for r in range(h) for c in range(w) if input_grid[r][c] == 3]

    output = [row[:] for row in input_grid]
    center_color = 4
    expand_color = 3

    for r, c in seed_pos:
        output[r][c] = center_color

    corners_by_edge = {0: [], w-1: []}
    for r, c in corner_pos:
        if c == 0:
            corners_by_edge[0].append(r)
        else:
            corners_by_edge[w-1].append(r)

    # For each row with right corner, fill from max_seed_col+1 to corner
    for r in corners_by_edge[w-1]:
        seeds_in_row = [c for pr, pc in seed_pos if pr == r]
        if seeds_in_row:
            max_seed = max(seeds_in_row)
            for c in range(max_seed + 1, w):
                output[r][c] = expand_color

    left_only_rows = set(corners_by_edge[0]) - set(corners_by_edge[w-1])
    for r in left_only_rows:
        output[r][1:] = [expand_color] * (w - 1)

    return output

